pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {AirDropContract} from "../src/AirDropContract.sol";

contract InvMutTest is Test {
    AirDropContract c;
    function setUp() public { c = new AirDropContract(); }

    function testFuzz_property(uint256 len, uint256 amt) public {
        uint256 n = bound(len, 1, 10);
        uint256 v = bound(amt, 1, 1e12);

        Recorder rec = new Recorder();

        address[] memory tos = new address[](n);
        uint[] memory vs = new uint[](n);
        for (uint i = 0; i < n; i++) {
            tos[i] = address(rec);
            vs[i] = v + i;
        }

        bool ok;
        try c.transfer(address(rec), tos, vs) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(rec.wasCalled(0), "index 0 must have been called");
    }
}

contract Recorder {
    mapping(uint => bool) public called;

    uint public calls;

    fallback() external payable {
        uint idx = calls;
        called[idx] = true;
        calls++;
    }

    function wasCalled(uint i) external view returns (bool) {
        return called[i];
    }
}
